package audit;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.annotation.EnableTransactionManagement;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Bean;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.jdbc.core.JdbcTemplate;
@Configuration
@EnableTransactionManagement(proxyTargetClass = true)
class Config {
    @Bean public DataSourceTransactionManager tx(javax.sql.DataSource ds) {
        return new DataSourceTransactionManager(ds);
    }
}
@Service
class Operations {
    @Autowired JdbcTemplate jdbc;
    Operations(javax.sql.DataSource ds) { jdbc.setDataSource(ds); }
    @Transactional public void two() {
        jdbc.execute("SELECT * FROM accounts");
        this.jdbc.update("DELETE FROM ledger");
    }
    @Transactional public void three() {
        jdbc.execute("SELECT * FROM accounts FOR UPDATE");
        this.jdbc.update("UPDATE ledger SET amount = 2");
        jdbc.queryForList("SELECT * FROM audit");
    }
    @Transactional public void barrier() {
        jdbc.execute("SELECT * FROM accounts");
        System.gc();
        jdbc.update("DELETE FROM ledger");
    }
}

